const TZ = 'Asia/Hebron';
const REQUIRED = ['Date', 'Order ID', 'Product', 'Quantity', 'Price', 'Customer'];

function ymd(d) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}
function pad(n) { return String(n).length < 2 ? '0' + n : String(n); }
function validYmd(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  if (s.length >= 10 && s.charAt(4) === '-' && s.charAt(7) === '-') {
    const y = Number(s.slice(0, 4)); const m = Number(s.slice(5, 7)); const d = Number(s.slice(8, 10));
    return validYmd(y, m, d) ? s.slice(0, 10) : null;
  }
  const p = s.split(' ')[0].split('/');
  if (p.length === 3 && p[2].length === 4) {
    const d = Number(p[0]); const m = Number(p[1]); const y = Number(p[2]);
    return validYmd(y, m, d) ? y + '-' + pad(m) + '-' + pad(d) : null;
  }
  return null;
}
function num(v) {
  if (typeof v === 'number') return v;
  const n = Number(String(v === undefined || v === null ? '' : v).split(',').join('').trim());
  return isNaN(n) ? 0 : n;
}
function round2(n) { return Math.round((n + Number.EPSILON) * 100) / 100; }

const today = ymd(new Date());
const yesterday = new Date(today + 'T12:00:00Z');
yesterday.setUTCDate(yesterday.getUTCDate() - 1);
const yesterdayStr = yesterday.toISOString().slice(0, 10);

const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);

function fail(message, status) {
  return [{ json: {
    status: status, date: today, message: message, ordersCount: 0, totalSales: 0, averageOrder: 0,
    topProduct: '', topProductRevenue: 0, topProducts: [], yesterdayTotal: 0, yesterdayOrders: 0, changePct: null,
  } }];
}

if (rows.length === 0) {
  return fail('⚠️ الجدول لا يحتوي على صفوف صالحة.', 'no_rows');
}

const keys = {};
rows.forEach((r) => Object.keys(r).forEach((k) => { keys[k] = true; }));
const missing = REQUIRED.filter((c) => !keys[c]);
if (missing.length > 0) {
  return fail('⚠️ أعمدة ناقصة في الجدول: ' + missing.join('، '), 'missing_columns');
}

let todayTotal = 0; let todayCount = 0; let yTotal = 0; let yCount = 0;
const byProduct = {};
rows.forEach((r) => {
  const d = parseDate(r['Date']);
  if (d === null) return;
  const revenue = num(r['Quantity']) * num(r['Price']);
  if (d === today) {
    todayTotal += revenue; todayCount += 1;
    const name = String(r['Product'] || 'غير معروف').trim();
    byProduct[name] = (byProduct[name] || 0) + revenue;
  } else if (d === yesterdayStr) {
    yTotal += revenue; yCount += 1;
  }
});

const ranked = Object.keys(byProduct)
  .map((name) => ({ product: name, revenue: round2(byProduct[name]) }))
  .sort((a, b) => b.revenue - a.revenue);

let changePct = null;
if (yTotal > 0) changePct = round2(((todayTotal - yTotal) / yTotal) * 100);

return [{ json: {
  status: 'ok',
  date: today,
  message: 'لا توجد مبيعات مسجلة اليوم',
  ordersCount: todayCount,
  totalSales: round2(todayTotal),
  averageOrder: todayCount > 0 ? round2(todayTotal / todayCount) : 0,
  topProduct: ranked.length ? ranked[0].product : '',
  topProductRevenue: ranked.length ? ranked[0].revenue : 0,
  topProducts: ranked.slice(0, 3),
  yesterdayTotal: round2(yTotal),
  yesterdayOrders: yCount,
  changePct: changePct,
} }];

