function esc(s) {
  return String(s === undefined || s === null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
}
const d = $('Calculate Numbers').first().json;
const insight = ($input.first().json.text || '').trim();
const pct = d.changePct;
let cmp;
if (pct === null) {
  cmp = '📈 مقارنة بالأمس: غير متاحة (لا مبيعات أمس)';
} else {
  const icon = pct >= 0 ? '📈' : '📉';
  const sign = pct > 0 ? '+' : '';
  cmp = icon + ' مقارنة بالأمس: ' + sign + pct + '%';
}
const top3 = d.topProducts
  .map((p, i) => (i + 1) + ') ' + esc(p.product) + ' (' + p.revenue + ')')
  .join('  ');
const lines = [
  '📊 <b>تقرير مبيعات اليوم — ' + esc(d.date) + '</b>',
  '💰 إجمالي المبيعات: ' + d.totalSales,
  '🧾 عدد الطلبات: ' + d.ordersCount,
  '📦 متوسط الطلب: ' + d.averageOrder,
  '🏆 الأكثر مبيعًا: ' + esc(d.topProduct) + ' (' + d.topProductRevenue + ')',
  cmp,
  '🔝 أفضل 3 منتجات: ' + top3,
];
if (insight) lines.push('💡 ' + esc(insight));
return [{ json: { message: lines.join(String.fromCharCode(10)) } }];
